#!/usr/bin/env python3\nimport sys,os\nsys.path.insert(0,str(Path(__file__).parent.parent))\nfrom bot.earning.backfill import run as backfill_run\nmc=int(os.getenv('BACKFILL_MAX_PER_CYCLE','50'))\nprint('running backfill with max_per_cycle='+str(mc)+'...')\nresult=backfill_run(llm=None,status={})\nif isinstance(result,dict):result=[result]\nif not result:print('backfill complete - no posts needed updating');sys.exit(0)\nfor a in result:\n if a.get('success'):print('✓ backfill added footer to post')\n else:print('✗ backfill failed: '+str(a.get('error','unknown'))[:100])\nu=sum(1 for a in result if a.get('success'))\nprint('backfill complete: '+str(u)+' posts updated, '+str(len(result)-u)+' skipped')